                } catch (err) {
                    terminalStatus = 'error'
                    terminalDescription = 'Stellar CPU CPU CI artifact archival failed.'
                    throw err
                } finally {
                    try {
                        if (candidateCommit) {
                            publishGitHubCommitStatus(
                                statusCredentialsId,
                                candidateCommit,
                                terminalStatus,
                                terminalDescription
                            )
                        }
                    } finally {
                        deleteDir()
                    }
                }
            }
        }
    }
