def writeCiTimingSummary() {
    sh '''#!/bin/bash
        set -euo pipefail

        metric() {
            local file="$1"
            if [[ -f "$file" ]]; then
                local value
                value="$(tr -d '[:space:]' < "$file")"
                if [[ -n "$value" ]]; then
                    printf '%s' "$value"
                    return
